import { PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, sin, texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const root = new Group();
  const ownedGeometries = [];
  const ownedMaterials = [];
  const primitiveResults = [];
  let disposed = false;

  const makeMaterial = (node, options = {}) => {
    const material = new MeshBasicNodeMaterial({
      transparent: options.transparent ?? false,
      opacity: options.opacity ?? 1,
      depthWrite: options.depthWrite ?? true
    });
    material.colorNode = node;
    ownedMaterials.push(material);
    return material;
  };

  const backdropUv = uv();
  const backdropBase = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    backdropUv.y
  );
  const grain = sin(
    backdropUv.x.mul(191.7).add(backdropUv.y.mul(83.4))
  ).mul(0.008);
  const backdropNode = backdropBase.add(vec3(grain));

  const backdropGeometry = new PlaneGeometry(7, 6);
  ownedGeometries.push(backdropGeometry);
  const backdrop = new Mesh(
    backdropGeometry,
    makeMaterial(backdropNode)
  );
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const shadowGeometry = new PlaneGeometry(3.15, 1.95);
  ownedGeometries.push(shadowGeometry);
  const shadowMaterial = makeMaterial(
    vec3(0.008, 0.008, 0.012),
    { transparent: true, opacity: 0.48, depthWrite: false }
  );
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0.08, -0.08, -0.12);
  shadow.scale.set(1.04, 1.04, 1);
  root.add(shadow);

  const frameGeometry = new PlaneGeometry(2.72, 1.82);
  ownedGeometries.push(frameGeometry);
  const frame = new Mesh(
    frameGeometry,
    makeMaterial(vec3(0.086, 0.086, 0.114))
  );
  frame.position.z = -0.04;
  root.add(frame);

  const cardGeometry = new PlaneGeometry(2.55, 1.6);
  ownedGeometries.push(cardGeometry);

  const cardMaterial = makeMaterial(vec3(0.086, 0.086, 0.114));
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.z = 0.02;
  root.add(card);

  const accentGeometry = new PlaneGeometry(0.055, 1.48);
  ownedGeometries.push(accentGeometry);
  const accent = new Mesh(
    accentGeometry,
    makeMaterial(vec3(1, 0.016, 0.024))
  );
  accent.position.set(-1.245, 0, 0.08);
  root.add(accent);

  const topRuleGeometry = new PlaneGeometry(1.18, 0.018);
  ownedGeometries.push(topRuleGeometry);
  const topRule = new Mesh(
    topRuleGeometry,
    makeMaterial(vec3(0.91, 0.925, 0.949))
  );
  topRule.position.set(0.42, 0.68, 0.09);
  root.add(topRule);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.color ?? '#e8ecf2',
      align: item.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.position.set(
      item.position?.x ?? -0.82,
      item.position?.y ?? 0,
      item.position?.z ?? 0.12
    );
    root.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) return;
      cardMaterial.colorNode = textureNode(texture, cardGeometry.attributes.uv);
      cardMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const cinematicPrimitives = config.cinematicPrimitives ?? [];
  for (const primitive of cinematicPrimitives) {
    if (!primitive?.name || !ctx.primitives?.[primitive.name]) continue;
    const result = ctx.primitives[primitive.name](
      root,
      primitive.params ?? {}
    );
    if (result) primitiveResults.push(result);
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const result of primitiveResults) {
      if (typeof result.cleanup === 'function') result.cleanup();
      if (result.timeline && typeof result.timeline.kill === 'function') {
        result.timeline.kill();
      }
    }

    root.traverse((object) => {
      if (object.geometry && !ownedGeometries.includes(object.geometry)) {
        object.geometry.dispose?.();
      }
      if (object.material && !ownedMaterials.includes(object.material)) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) material.dispose?.();
      }
    });

    for (const geometry of ownedGeometries) geometry.dispose();
    for (const material of ownedMaterials) material.dispose();
  };

  return root;
}
